insert = needle + '''\n    static void configureMotion(String mode, float followStrength, float deadZone, float fixedX, float fixedY) {\n        if (mode == null) mode = "Slow";\n        if (!"Fixed center".equals(mode) && !"Fixed actor average".equals(mode) && !"Manual fixed".equals(mode)\n                && !"Very slow".equals(mode) && !"Slow".equals(mode) && !"Normal".equals(mode) && !"Custom".equals(mode)) mode = "Slow";\n        CFG_MOTION_MODE = mode;\n        CFG_FOLLOW_STRENGTH = clamp(followStrength, 0f, 1f);\n        CFG_DEAD_ZONE = clamp(deadZone, 0f, 0.30f);\n        CFG_FIXED_X = clamp(fixedX, 0.08f, 0.92f);\n        CFG_FIXED_Y = clamp(fixedY, 0.08f, 0.92f);\n    }\n'''
