new = '''        Center center = motionCenter(globalMs);\n        boolean fixedCamera = isFixedMode() || !tracking;\n        float cx = center.x;\n        float cy = center.y;\n\n        float zoom = 1f;\n        if (CFG_DYNAMIC_ZOOM && tracking && !fixedCamera) {'''
