marker = '    private float compositionTargetX(long globalMs, float cx) {'
methods = '''    private boolean isFixedMode() {\n        return "Fixed center".equals(CFG_MOTION_MODE) || "Fixed actor average".equals(CFG_MOTION_MODE) || "Manual fixed".equals(CFG_MOTION_MODE);\n    }\n\n    private Center motionCenter(long globalMs) {\n        if (!tracking || "Fixed center".equals(CFG_MOTION_MODE))\n            return new Center(0.50f, 0.50f, 1f);\n        Center anchor = wholeSegmentCenter();\n        if ("Fixed actor average".equals(CFG_MOTION_MODE)) return anchor;\n        if ("Manual fixed".equals(CFG_MOTION_MODE)) return new Center(CFG_FIXED_X, CFG_FIXED_Y, 1f);\n\n        float strength; long radius; double sigma;\n        if ("Very slow".equals(CFG_MOTION_MODE)) { strength = 0.12f; radius = 7000L; sigma = 2800.0; }\n        else if ("Slow".equals(CFG_MOTION_MODE)) { strength = 0.24f; radius = 5600L; sigma = 2100.0; }\n        else if ("Normal".equals(CFG_MOTION_MODE)) { strength = 0.62f; radius = 3200L; sigma = 1100.0; }\n        else {\n            strength = CFG_FOLLOW_STRENGTH;\n            radius = (long)(2600L + (1f - strength) * 5200L);\n            sigma = 850.0 + (1f - strength) * 2500.0;\n        }\n        Center raw = wideCenter(globalMs, radius, sigma);\n        float dx = raw.x - anchor.x, dy = raw.y - anchor.y;\n        float dz = CFG_DEAD_ZONE;\n        dx = Math.abs(dx) <= dz ? 0f : Math.copySign(Math.abs(dx) - dz, dx);\n        dy = Math.abs(dy) <= dz * 0.75f ? 0f : Math.copySign(Math.abs(dy) - dz * 0.75f, dy);\n        float x = clamp(anchor.x + dx * strength, 0.08f, 0.92f);\n        float y = clamp(anchor.y + dy * strength, 0.08f, 0.92f);\n        return new Center(x, y, raw.confidence);\n    }\n\n    private Center wideCenter(long globalMs, long radius, double sigma) {\n        double sx = 0, sy = 0, sw = 0, conf = 0;\n        ActorScanStore.Hit previousAccepted = null;\n        for (ActorScanStore.Hit h : hits) {\n            long dt = Math.abs(h.t - globalMs);\n            if (dt > radius) continue;\n            if (CFG_IDENTITY_LOCK && previousAccepted != null && isIdentityJump(previousAccepted, h)) continue;\n            double temporal = Math.exp(-0.5 * Math.pow(dt / Math.max(300.0, sigma), 2.0));\n            double confidence = Math.max(0.12, h.quality + 0.28) * Math.max(0.20, h.score + 0.18);\n            double w = temporal * confidence;\n            sx += h.cx * w; sy += h.cy * w; sw += w;\n            conf += clamp(h.quality * 0.65f + h.score * 0.35f, 0f, 1f) * w;\n            previousAccepted = h;\n        }\n        if (sw > 1e-6) return new Center((float)(sx/sw), (float)(sy/sw), (float)(conf/sw));\n        return smoothCenter(globalMs);\n    }\n\n    private float dampedCompositionTargetX(long globalMs, float cx) {\n        float raw = compositionTargetX(globalMs, cx);\n        float k;\n        if ("Very slow".equals(CFG_MOTION_MODE)) k = 0.08f;\n        else if ("Slow".equals(CFG_MOTION_MODE)) k = 0.16f;\n        else if ("Normal".equals(CFG_MOTION_MODE)) k = 0.55f;\n        else k = CFG_FOLLOW_STRENGTH;\n        return 0.5f + (raw - 0.5f) * clamp(k, 0f, 1f);\n    }\n\n'''
if marker not in s:
    raise SystemExit('composition insertion point missing')
s = s.replace(marker, methods + marker, 1)
track.write_text(s)

